        let next = null;
        const n = raw.next;
        if (!closing && change !== 'note' && n && typeof n === 'object') {
            const what = clean(n.what, 120);
            if (what) next = { what, label: null, by: date(n.by), how: 'none', reply: null, url: null, yours: n.yours === true, isTask: false };
        }
